26	
27	    @Mapping(target = "displayName",
28	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
29	    @Mapping(target = "initials", expression = "java(initials(owner))")
30	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
32	    @Mapping(target = "locality", expression = "java(locality(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "identityKey", expression = "java(IdentityKey.of(owner))")
36	    // Not derivable from a single owner; the responder sets it from the daily registration count.
37	    @Mapping(target = "bulkSignupWarning", ignore = true)
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * The owner's locality: the REGION segment of its customer-code identity (see
42	     * {@link CustomerCode#regionOf(String)}), which is the region derived from the
43	     * owner's postcode then city when the code was assigned.
44	     */
45	    default String locality(Owner owner) {
46	        return CustomerCode.regionOf(owner.getCustomerCode());
47	    }
48	
49	    /**
