51	     * otherwise "PHONE".
52	     *
53	     * @see ContactPreference#of(Owner)
54	     */
55	    default String contactPreference(Owner owner) {
56	        return ContactPreference.of(owner);
57	    }
58	
59	    /**
60	     * The owner's age band, derived from its birth date against its registration date.
61	     *
62	     * @see AgeBand#of(Owner)
63	     */
64	    default String ageBand(Owner owner) {
65	        return AgeBand.of(owner);
66	    }
67	
68	    /**
69	     * The owner's membership level from 1 to 3, assigned on creation.
70	     *
71	     * @see MembershipLevel#of(Owner)
72	     */
73	    default Integer membershipLevel(Owner owner) {
74	        return MembershipLevel.of(owner);
75	    }
76	
77	    /**
78	     * The Luhn check digit (0-9) over the digits of the owner's customer code.
79	     *
80	     * @see Luhn#checkDigit(String)
81	     */
82	    default Integer checkDigit(Owner owner) {
83	        return Luhn.checkDigit(owner.getCustomerCode());
84	    }
85	
86	    /**
87	     * The upper-cased first letters of firstName and lastName, dot-separated with a
88	     * trailing dot (e.g. "J.S.").
89	     */
90	    default String initials(Owner owner) {
91	        return firstInitial(owner.getFirstName()) + firstInitial(owner.getLastName());
92	    }
93	
94	    private static String firstInitial(String name) {
95	        return Character.toUpperCase(name.charAt(0)) + ".";
96	    }
97	
98	    Owner toOwner(OwnerDto ownerDto);
99	
100	    @Mapping(target = "id", ignore = true)
101	    @Mapping(target = "pets", ignore = true)
102	    Owner toOwner(OwnerFieldsDto ownerDto);
103	
104	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
105	
106	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
107	
108	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
109	        OwnerPageDto ownerPageDto = new OwnerPageDto();
110	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
111	        ownerPageDto.setPage(ownerPage.getNumber());
112	        ownerPageDto.setSize(ownerPage.getSize());
113	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
114	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
115	        return ownerPageDto;
116	    }
117	}
